def seed_db():
    if User.query.count() == 0:
        for user_data in USERS:
            user = User(**user_data)
            db.session.add(user)
        db.session.commit()
        print("Database seeded with initial users.")

    if AirWayBill.query.count() == 0:
        admin = User.query.filter_by(email="admin@example.com").first()
        awbs = _awbs(admin.id if admin else None)
        db.session.add_all(awbs)
        db.session.commit()
        print(f"Database seeded with {len(awbs)} air waybills.")
